    }
    const scriptPath = path.resolve(process.cwd(), relativeScriptPath);
    const port = await getPort();
    let server;
    const cleanup = async () => {
        if (server) {
            await server.close();
        }
        process.exit();
    };
    process.on("SIGINT", cleanup);
    process.on("SIGTERM", cleanup);
    try {
