        const readyUrl = await checkServerUp(`http://localhost:${port}`, "/__debug", 30, false);
        const readyOrigin = new URL(readyUrl).origin;
        const readyOriginUrl = new URL(readyOrigin);
        const candidateBaseUrls = Array.from(new Set([
